def rencontres_number(n, m):
    if m == 1:
        return 0
    elif m == 2:
        return 1

    # Initialize the first few terms of the sequence
    c = [1] * (m + 1)

    # Calculate the nth term using the recurrence relation
    for i in range(2, n + 1):
        for j in range(i, 0, -1):
            c[j] += c[i - j]

    return c[m]
```

